-- TSE Tracker database schema + seed data for Supabase (PostgreSQL)
-- Run this whole file once in the Supabase SQL Editor.

drop table if exists public.tasks cascade;
create table public.tasks (
  id text primary key,
  task text,
  assigned text,
  date text,
  status text,
  created_at bigint
);
alter table public.tasks enable row level security;
create policy "allow all - tasks" on public.tasks for all using (true) with check (true);
alter publication supabase_realtime add table public.tasks;

drop table if exists public.sites cascade;
create table public.sites (
  id text primary key,
  cluster text,
  name text,
  tse text,
  hours text,
  sched text,
  datedone text,
  mark text
);
alter table public.sites enable row level security;
create policy "allow all - sites" on public.sites for all using (true) with check (true);
alter publication supabase_realtime add table public.sites;

drop table if exists public.inventory cascade;
create table public.inventory (
  id text primary key,
  branch text,
  device_name text,
  serial text,
  pagcor text,
  mac text,
  color text,
  device_type text,
  anydesk text,
  date_deployed text,
  date_purchase text,
  note text,
  alias text
);
alter table public.inventory enable row level security;
create policy "allow all - inventory" on public.inventory for all using (true) with check (true);
alter publication supabase_realtime add table public.inventory;

drop table if exists public.monitors cascade;
create table public.monitors (
  id text primary key,
  branch text,
  terminal text,
  serial text,
  pagcor text,
  screen_size text,
  brand text,
  date_purchase text,
  remarks text
);
alter table public.monitors enable row level security;
create policy "allow all - monitors" on public.monitors for all using (true) with check (true);
alter publication supabase_realtime add table public.monitors;

drop table if exists public.lakiwin_sites cascade;
create table public.lakiwin_sites (
  id text primary key,
  site_name text,
  operator text,
  outlet_id text,
  game_offering text,
  address text,
  date_installation text,
  launching_date text,
  contact_person text,
  designation text,
  contact_number text,
  terminal text,
  tablet text,
  power_adapter text,
  additional_tablet text,
  vnc_installed text,
  map_link text,
  status text,
  notes text
);
alter table public.lakiwin_sites enable row level security;
create policy "allow all - lakiwin_sites" on public.lakiwin_sites for all using (true) with check (true);
alter publication supabase_realtime add table public.lakiwin_sites;

drop table if exists public.anydesk_ids cascade;
create table public.anydesk_ids (
  id text primary key,
  site text,
  terminal text,
  anydesk_id text,
  type text,
  remarks text,
  hardware_add text,
  url_status text
);
alter table public.anydesk_ids enable row level security;
create policy "allow all - anydesk_ids" on public.anydesk_ids for all using (true) with check (true);
alter publication supabase_realtime add table public.anydesk_ids;





